
let selectedKey=null,selectedTitleText='',collectionRows=[],treeData=[],locationSet=new Set(),proposedWatch=null;
let librarySelected=new Set();
let libOpen=new Set(),locOpen=new Set(),newFolderParent=null,candidateSelected=new Set(),lastWatchSettings=null,watchTab='candidates',watchData={candidates:[],maybe:[],history:[]};
async function api(p,o){let r=await fetch(p,o),j=await r.json();if(!r.ok)throw Error(j.message||j.error||r.status);return j}
function esc(s){return String(s||'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;')}
function highlightText(s){ return esc(s); }

function normalizeMathText(value){
  let s=String(value||'');
  // Research Cards mostly contain compact scientific quantities, not display equations.
  // Convert common LaTeX to readable Unicode/plain text; unknown LaTeX remains readable text.
  const greek={alpha:'α',beta:'β',gamma:'γ',delta:'δ',epsilon:'ε',theta:'θ',lambda:'λ',mu:'μ',pi:'π',rho:'ρ',sigma:'σ',tau:'τ',phi:'φ',chi:'χ',psi:'ψ',omega:'ω',Delta:'Δ',Gamma:'Γ',Lambda:'Λ',Sigma:'Σ',Phi:'Φ',Psi:'Ψ',Omega:'Ω'};
  const sup={'0':'⁰','1':'¹','2':'²','3':'³','4':'⁴','5':'⁵','6':'⁶','7':'⁷','8':'⁸','9':'⁹','+':'⁺','-':'⁻','n':'ⁿ'};
  const sub={'0':'₀','1':'₁','2':'₂','3':'₃','4':'₄','5':'₅','6':'₆','7':'₇','8':'₈','9':'₉','+':'₊','-':'₋','a':'ₐ','e':'ₑ','h':'ₕ','i':'ᵢ','j':'ⱼ','k':'ₖ','l':'ₗ','m':'ₘ','n':'ₙ','o':'ₒ','p':'ₚ','r':'ᵣ','s':'ₛ','t':'ₜ','u':'ᵤ','v':'ᵥ','x':'ₓ'};
  s=s.replace(/\\times/g,'×').replace(/\\cdot/g,'·').replace(/\\pm/g,'±').replace(/\\leq?/g,'≤').replace(/\\geq?/g,'≥').replace(/\\neq/g,'≠').replace(/\\approx/g,'≈').replace(/\\infty/g,'∞');
  s=s.replace(/\\([A-Za-z]+)/g,(m,k)=>greek[k]||m);
  s=s.replace(/\^\{([0-9+\-n]+)\}/g,(m,x)=>[...x].map(c=>sup[c]||c).join(''));
  s=s.replace(/\^([0-9])/g,(m,x)=>sup[x]||x);
  s=s.replace(/_\{([0-9A-Za-z+\-]+)\}/g,(m,x)=>[...x].map(c=>sub[c]||c).join(''));
  s=s.replace(/_([0-9A-Za-z])/g,(m,x)=>sub[x]||x);
  s=s.replace(/\\mathrm\{([^{}]+)\}/g,'$1').replace(/\\text\{([^{}]+)\}/g,'$1');
  s=s.replace(/\$\$([\s\S]*?)\$\$/g,'$1').replace(/\$([^$\n]+)\$/g,'$1').replace(/\\\((.*?)\\\)/g,'$1').replace(/\\\[(.*?)\\\]/g,'$1');
  s=s.replace(/\\,/g,' ').replace(/\\;/g,' ').replace(/\\!/g,'');
  return s;
}
function mathEsc(s){return esc(normalizeMathText(s));}
function dateOnly(v){let s=String(v||'');let m=s.match(/^(\d{4}-\d{2}-\d{2})/);return m?m[1]:s}
function stripPriority(v){return String(v||'').replace(/\s*\|\s*Priority\s*:\s*[^|\n]+(?=\s*\||$)/ig,'').replace(/(^|\n)\s*Priority\s*:\s*[^\n]+/ig,'$1').replace(/\s*\|\s*\|\s*/g,' | ').trim()}

function closeModal(id){document.getElementById(id).style.display='none'}
function openModal(id){document.getElementById(id).style.display='flex'}
async function refreshStatus(){try{let s=await api('/status');online.textContent='Service Online';model.textContent='Model: '+s.model;let ve=document.getElementById('appVersion');if(ve){ve.textContent='v'+(s.version||'')}else{let h=document.querySelector('.top h1, h1');if(h&&s.version){let spans=[...h.querySelectorAll('span')],vs=spans.find(x=>/^v\d+\.\d+\.\d+$/i.test((x.textContent||'').trim()));if(vs)vs.textContent='v'+s.version}}task.textContent=(s.running?'Running: '+s.mode:'Idle')+(s.last_result?' · Last: '+s.last_result:'')+(s.last_error?' · Error: '+s.last_error:'')}catch(e){online.textContent='Offline'}}
function libraryFolder(n,depth=0){let open=libOpen.has(n.key);let has=(n.children||[]).length||(n.items||[]).length;let kids='';if(open){kids+=(n.items||[]).map(p=>`<div class="paperline ${selectedKey===p.key?'selected':''}"><input class="librarySelect" type="checkbox" ${librarySelected.has(p.key)?'checked':''} onclick="event.stopPropagation()" onchange="toggleLibrarySelected('${p.key}',this.checked)"><span class="paperTitle" onclick="selectItem('${p.key}',this)">📄 ${esc(p.title)}</span><span class="${p.summarized?'ok':(p.has_pdf?'warn':'err')}">●</span></div>`).join('');kids+=(n.children||[]).map(c=>libraryFolder(c,depth+1)).join('')}return `<div><div class="folderline"><span class="twisty" onclick="toggleLib('${n.key}')">${has?(open?'⌄':'›'):''}</span><span class="folder" onclick="toggleLib('${n.key}')">📁 ${esc(n.name)}</span></div>${open?`<div class="children">${kids}</div>`:''}</div>`}
function toggleLib(k){libOpen.has(k)?libOpen.delete(k):libOpen.add(k);renderLibrary()}
function renderLibrary(){libraryTree.innerHTML=treeData.map(n=>libraryFolder(n)).join('')||'No numeric collections.'}
function renameFolderTree(nodes,parts=[]){return nodes.map(n=>{let p=[...parts,n.name];return `<div><div class="locrow"><span class="twisty">${(n.children||[]).length?'⌄':''}</span><span class="locname">📁 ${esc(n.name)} <span class="muted">${esc(p.join(' -> '))}</span></span><button class="secondary smallbtn" onclick="renameFolder('${n.key}','${esc(n.name).replaceAll("'","&#39;")}')">Rename</button></div><div class="locchildren">${renameFolderTree(n.children||[],p)}</div></div>`}).join('')}
function openRenameManager(){renameTree.innerHTML=renameFolderTree(treeData);renameMsg.textContent='';openModal('renameModal')}
async function renameFolder(key,oldName){let name=prompt('New folder name:',oldName);if(name===null)return;name=name.trim();if(!name||name===oldName)return;try{renameMsg.textContent='Renaming…';let x=await api('/collections/rename',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key,name})});renameMsg.textContent=x.message+' ✓';await waitForCache();await refreshTrees();renameTree.innerHTML=renameFolderTree(treeData)}catch(e){renameMsg.textContent='Error: '+e.message}}
let missingPdfRows=[],missingPdfSelected=new Set();
async function openPdfRecovery(){openModal('pdfRecoveryModal');await loadMissingPdfs()}
async function loadMissingPdfs(){missingPdfList.innerHTML='Loading missing-PDF papers…';pdfRecoveryMsg.textContent='';try{let x=await api('/pdf-recovery/missing');missingPdfRows=x.items||[];missingPdfSelected.clear();renderMissingPdfs()}catch(e){missingPdfList.textContent='Error: '+e.message}}
function renderMissingPdfs(){
  let groups=new Map();
  for(const r of missingPdfRows){let loc=(r.locations&&r.locations[0])||'Unfiled';if(!groups.has(loc))groups.set(loc,[]);groups.get(loc).push(r)}
  let html=''; let gi=0;
  for(const [loc,rows] of groups){
    let gid='pdfGroup'+(gi++), keys=rows.map(r=>r.key);
    html+=`<div style="margin:10px 0 4px;font-weight:700;display:flex;align-items:center;gap:8px"><input class="missingGroupCheck" id="${gid}" type="checkbox" onchange='selectMissingGroup(${JSON.stringify(keys)},this.checked)'>📁 ${esc(loc)}</div>`+
      rows.map(r=>`<div class="paperline" style="margin-left:20px;align-items:flex-start"><input class="missingCheck" data-key="${r.key}" type="checkbox" ${missingPdfSelected.has(r.key)?'checked':''} onchange="toggleMissing('${r.key}',this.checked)" style="margin-top:7px"><div style="margin-left:7px;min-width:0"><div style="white-space:normal">📄 ${esc(r.title)}</div><div class="muted">${esc(r.year||'')} ${r.doi?'· DOI '+esc(r.doi):'· DOI unavailable'} ${r.has_card?'· Research Card preserved':''}</div></div></div>`).join('');
  }
  missingPdfList.innerHTML=html||'<span class="ok">No missing PDFs.</span>';
  updateMissingCount(); updateMissingCheckboxStates();
}
function selectMissingGroup(keys,on){for(const k of keys){on?missingPdfSelected.add(k):missingPdfSelected.delete(k)};document.querySelectorAll('.missingCheck').forEach(c=>c.checked=missingPdfSelected.has(c.dataset.key));updateMissingCount();updateMissingCheckboxStates()}
function updateMissingCheckboxStates(){
  let allKeys=missingPdfRows.map(r=>r.key), selected=allKeys.filter(k=>missingPdfSelected.has(k)).length;
  pdfSelectAll.checked=allKeys.length>0&&selected===allKeys.length; pdfSelectAll.indeterminate=selected>0&&selected<allKeys.length;
  let groups=new Map();for(const r of missingPdfRows){let loc=(r.locations&&r.locations[0])||'Unfiled';if(!groups.has(loc))groups.set(loc,[]);groups.get(loc).push(r.key)}
  let i=0;for(const keys of groups.values()){let el=document.getElementById('pdfGroup'+(i++));if(!el)continue;let n=keys.filter(k=>missingPdfSelected.has(k)).length;el.checked=n===keys.length&&keys.length>0;el.indeterminate=n>0&&n<keys.length}
}
function toggleMissing(k,on){on?missingPdfSelected.add(k):missingPdfSelected.delete(k);updateMissingCount();updateMissingCheckboxStates()}
function selectAllMissing(on){missingPdfSelected.clear();document.querySelectorAll('.missingCheck').forEach(c=>{c.checked=on;if(on)missingPdfSelected.add(c.dataset.key)});updateMissingCount();updateMissingCheckboxStates()}
function updateMissingCount(){pdfSelectedCount.textContent=missingPdfSelected.size+' selected'}
async function recoverSelectedPdfs(){if(!missingPdfSelected.size)return;let keys=[...missingPdfSelected];pdfRecoveryMsg.textContent='Checking legal open-access sources for '+keys.length+' paper(s)…';try{let x=await api('/pdf-recovery/run',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({item_keys:keys})});let resultHtml=x.results.map(r=>`${r.ok?'✓':'○'} ${esc(r.title||r.key)} — ${esc(r.message)}`).join('<br>');await refreshCounts();await refreshTrees();let y=await api('/pdf-recovery/missing');missingPdfRows=y.items||[];missingPdfSelected.clear();renderMissingPdfs();pdfRecoveryMsg.innerHTML=resultHtml}catch(e){pdfRecoveryMsg.textContent='Error: '+e.message}}

async function refreshTrees(){let x=await api('/cache');treeData=x.tree||[];collectionRows=[];function rows(nodes,parts=[]){for(const n of nodes){let p=[...parts,n.name];collectionRows.push({key:n.key,name:n.name,path:p.join(' -> '),parts:p});rows(n.children||[],p)}}rows(treeData);treeData.forEach(n=>libOpen.add(n.key));renderLibrary();let ks=document.getElementById('knowledgeScope');if(ks){let prev=ks.value;ks.innerHTML='<option value="">Entire Library</option>'+collectionRows.map(r=>`<option value="${esc(r.key)}">${esc(r.path)}</option>`).join('');if([...ks.options].some(o=>o.value===prev))ks.value=prev}if(!x.ready&&x.syncing){msg.textContent='Syncing Zotero in background…'}}
async function selectItem(k){
selectedKey=k;renderLibrary();
let title='';for(const root of treeData){const q=[root];while(q.length){const n=q.shift(),hit=(n.items||[]).find(p=>p.key===k);if(hit){title=hit.title;break}q.push(...(n.children||[]))}if(title)break}
selectedTitleText=title||'Selected paper';selectedTitle.textContent=selectedTitleText;locPaperTitle.textContent=selectedTitleText;inlineCardTitle.textContent=selectedTitleText;
paperActions.style.display='flex';paperOverview.innerHTML='<span class="muted">Loading paper memory…</span>';paperActivity.style.display='none';inlineCard.innerHTML='';
try{let x=await api('/item/'+k+'/memory');if(selectedKey!==k)return;renderPaperMemory(x)}catch(e){if(selectedKey===k)paperOverview.innerHTML='<span class="err">Could not load paper: '+esc(e.message)+'</span>'}
}
function renderPaperMemory(x){let r=x.item||{},c=r.card||{},cl=r.classifications||{},na=x.next_action||{};selectedTitleText=r.title||selectedTitleText;selectedTitle.textContent=selectedTitleText;locPaperTitle.textContent=selectedTitleText;inlineCardTitle.textContent=selectedTitleText;window._currentPaperMeta={published:r.published||'',date_added:r.date_added||'',year:r.year||''};window._paperNextAction=na;
let badges=[r.year||'',r.has_pdf?'PDF':'No PDF',r.has_card?'Research Card':'No Card',Number(r.duplicate_count||1)>1?(r.duplicate_count+' Zotero records'):''].filter(Boolean).map(v=>`<span class="paperBadge">${esc(v)}</span>`).join('');
let cls=[cl.paper_type,cl.research_area].filter(Boolean).map(v=>`<span class="paperBadge subtle">${esc(v)}</span>`).join('');
paperOverview.innerHTML=`<div class="paperBadges">${badges}${cls}</div><div class="paperFacts"><div><b>DOI</b> ${esc(r.doi||'Unavailable')}</div><div><b>Location</b> ${esc((r.locations||[]).join(' · ')||'Unfiled')}</div></div><details class="paperAbstract"><summary><b>Abstract</b></summary><div>${mathEsc(r.abstract||'No abstract available.')}</div></details>`;
let acts=x.activity||[], comps=x.comparisons||[];paperActivity.style.display='block';paperActivity.innerHTML=`<div class="paperSectionTitle">Activity</div>${acts.length?acts.map(a=>`<div class="paperActivityRow">✓ ${esc(a.label)}</div>`).join(''):'<div class="muted">No saved analyses yet.</div>'}${comps.length?`<div class="paperComparisonLinks">${comps.map(q=>`<a onclick="openSavedComparison('${q.id}')">${esc(q.label)}</a>`).join('')}</div>`:''}<div class="paperNext"><b>Next</b> ${esc(na.reason||'')}</div>`;
let b=document.getElementById('paperPrimaryBtn');if(na.kind==='ready'){b.textContent='Re-analyze';b.className='secondary smallbtn'}else{b.textContent=na.label||'Analyze';b.className='smallbtn'};
if(c){renderResearchCard(c);showRecommendation(c.recommended_collection||'')}else{inlineCard.innerHTML='<div class="paperNoCard"><b>Research Card</b><br><span class="muted">No Research Card yet.</span></div>';recommend.classList.add('hidden')}
}
async function runPaperPrimaryAction(){if(!selectedKey)return;let a=(window._paperNextAction||{}).kind;if(a==='find_pdf'){await openPdfRecovery();missingPdfSelected.clear();missingPdfSelected.add(selectedKey);renderMissingPdfs();return}if(a==='file'){openLocation();return}let b=document.getElementById('paperPrimaryBtn'),old=b.textContent,keyAtStart=selectedKey;b.disabled=true;b.textContent='Analyzing…';paperActivity.style.display='block';paperActivity.innerHTML='<div class="paperSectionTitle">Activity</div><div class="paperActivityRow">⏳ Starting analysis…</div>';try{let force=(a==='ready');let r=await api('/process/manual',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({item_key:keyAtStart,force})});paperActivity.innerHTML='<div class="paperSectionTitle">Activity</div><div class="paperActivityRow">⏳ '+esc(r.message||'Analysis started')+'</div>';await waitForManualJob(r.item_key||keyAtStart);await refreshCounts();await refreshTrees();if(selectedKey===keyAtStart)await selectItem(keyAtStart)}catch(e){paperActivity.style.display='block';paperActivity.innerHTML='<div class="paperSectionTitle">Activity</div><div class="err">Analysis failed: '+esc(e.message)+'</div>'}finally{b.disabled=false;if(b.textContent==='Analyzing…')b.textContent=old}}
async function waitForManualJob(k){let seen=false,lastStage='';for(let i=0;i<420;i++){await new Promise(r=>setTimeout(r,500));let s=await api('/status');if(s.stage_message&&s.stage_message!==lastStage){lastStage=s.stage_message;paperActivity.style.display='block';paperActivity.innerHTML='<div class=\"paperSectionTitle\">Activity</div><div class=\"paperActivityRow\">⏳ '+esc(s.stage_message)+'</div>'}if(s.running){seen=true;continue}if(seen||s.finished_at){if(s.last_error)throw Error(s.last_error);return}}throw Error('Analysis status polling timed out')}
function openCard(){if(!selectedKey)return;openModal('cardModal')}
async function renderResearchCard(c){
  const section=(title,body)=>body?`<div class="rcSection"><h3><strong>${esc(title)}</strong></h3><div class="body">${mathEsc(body)}</div></div>`:'';
  if(c.quick_meta||c.problem||c.approach||c.results){
    let pm=window._currentPaperMeta||{};let pub=dateOnly(pm.published||pm.year||'');let added=pm.date_added||'';let metaPrefix=pub?`<div style="font-weight:700;margin-bottom:5px">Published: ${esc(pub)}</div>`:'';let addedLine=added?`<div class="muted" style="margin:-7px 0 12px">Added to library: ${esc(added.replace('T',' ').replace('Z',''))}</div>`:'';inlineCard.innerHTML=metaPrefix+(c.quick_meta?`<div class="rcMetaStrong">${mathEsc(stripPriority(c.quick_meta)).replace(/^(Line\s*[123]\s*:\s*)/gim,'')}</div>`:'')+addedLine+
      section('PROBLEM',c.problem)+section('APPROACH',c.approach)+section('RESULTS',c.results)+
      section('LIMITATIONS',c.limitations)+section('REPRODUCIBILITY',c.reproducibility)+section('KEYWORDS',c.keywords);
    inlineCard.scrollTop=0; return;
  }
  // Legacy cards: emphasize structure only. No keyword guessing and no re-analysis required.
  const splitRationale=(value)=>{
    let t=String(value||'').trim();
    let m=t.match(/^(.*?)(?:\n|\s+)Rationale:\s*([\s\S]*)$/i);
    return m?{main:m[1].trim(),rationale:m[2].trim()}:{main:t,rationale:''};
  };
  let pr=splitRationale(c.priority), ev=splitRationale(c.evidence), mv=splitRationale(c.methodological_value), nv=splitRationale(c.novelty);
  let first=[c.paper_type,c.research_area,ev.main?('Evidence '+ev.main):''].filter(Boolean).join(' · ');
  let html=`<div class="rcMetaStrong">${mathEsc(first)}${c.methodology?'\n'+mathEsc(c.methodology):''}</div>`;
  const labeled=(label,text)=>text?`<div class="rcLabel">${esc(label)}</div><div class="rcText">${mathEsc(text)}</div>`:'';
  html+=labeled('EVIDENCE RATIONALE',ev.rationale);
  html+=labeled('METHODOLOGICAL VALUE',mv.main)+(mv.rationale?labeled('RATIONALE',mv.rationale):'');
  html+=labeled('NOVELTY',nv.main)+(nv.rationale?labeled('RATIONALE',nv.rationale):'');
  html+=labeled('WHY IT MATTERS',c.why_it_matters);
  html+=labeled('CITATION',c.citation_role);
  inlineCard.innerHTML=html||'<div class="rcLegacy">Legacy Research Card.</div>';
  inlineCard.scrollTop=0;
}
async function openLocation(){if(!selectedKey)return;await loadLocations();openModal('locationModal')}
function locFolder(n,depth=0){let open=locOpen.has(n.key);let has=(n.children||[]).length;let inline=newFolderParent===n.key?`<div class="newfolder">📁 <input id="newFolderInput" value="New folder" onkeydown="newFolderKey(event,'${n.key}')" onblur="cancelNewFolderLater()"><button class="smallbtn" onclick="commitNewFolder('${n.key}')">Create</button></div>`:'';let kids=open?(n.children||[]).map(c=>locFolder(c,depth+1)).join(''):'';return `<div><div class="locrow"><input type="checkbox" ${locationSet.has(n.key)?'checked':''} onchange="toggleLocation('${n.key}',this.checked)"><span class="twisty" onclick="toggleLoc('${n.key}')">${has?(open?'⌄':'›'):''}</span><span class="locname" onclick="toggleLoc('${n.key}')">📁 ${esc(n.name)}</span><button class="locplus" title="New subfolder" onclick="startNewFolder('${n.key}',event)">+</button></div>${inline}${open?`<div class="locchildren">${kids}</div>`:''}</div>`}
function renderLocation(){locationTree.innerHTML=`<div class="locrow"><span class="twisty">⌄</span><span class="locname" style="font-weight:650">💻 My Library</span></div><div class="locchildren">${treeData.map(n=>locFolder(n)).join('')}</div>`;if(newFolderParent){setTimeout(()=>{let i=document.getElementById('newFolderInput');if(i){i.focus();i.select()}},0)}}
function toggleLoc(k){locOpen.has(k)?locOpen.delete(k):locOpen.add(k);renderLocation()}
function toggleLocation(k,v){v?locationSet.add(k):locationSet.delete(k)}
function startNewFolder(k,e){e.stopPropagation();newFolderParent=k;locOpen.add(k);renderLocation()}
function newFolderKey(e,k){if(e.key==='Enter'){e.preventDefault();commitNewFolder(k)}else if(e.key==='Escape'){newFolderParent=null;renderLocation()}}
function cancelNewFolderLater(){setTimeout(()=>{if(newFolderParent){newFolderParent=null;renderLocation()}},180)}
async function commitNewFolder(parentKey){let i=document.getElementById('newFolderInput');if(!i)return;let name=i.value.trim();if(!name)return;newFolderParent=null;try{let r=await api('/collections/create',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,parent_key:parentKey})});filingMsg.textContent=r.message;await refreshTrees();locOpen.add(parentKey);await loadLocations()}catch(e){filingMsg.textContent=e.message}}
function norm(p){return String(p||'').replaceAll('→','->').replaceAll('/','->').split('->').map(x=>x.trim()).filter(Boolean).join(' -> ')}
function recommendationPaths(raw){
  let t=String(raw||'').replaceAll('→','->').trim();
  if(!t)return [];
  // Split concatenated recommendations whenever another numeric top-level collection starts.
  let chunks=t.split(/\s+(?=\d{2}_[A-Za-z0-9])/g);
  return chunks.map(norm).filter(Boolean);
}
function resolveRecommendationRoot(path){
  let parts=String(path||'').split(' -> ').filter(Boolean);if(!parts.length)return path;
  if(collectionRows.some(x=>x.path===path))return path;
  let m=parts[0].match(/^(\d{2})(?:[_\- &]|$)/);if(!m)return path;
  let roots=collectionRows.filter(x=>x.parts&&x.parts.length===1&&String(x.name||'').startsWith(m[1]));
  if(roots.length===1){parts[0]=roots[0].name;return parts.join(' -> ')}
  return path;
}
function showRecommendation(raw){
  let original=recommendationPaths(raw),paths=original.map(resolveRecommendationRoot);if(!paths.length){recommend.classList.add('hidden');return}
  recommend.classList.remove('hidden');
  recommend.innerHTML='<b>★ AI recommendations</b><br>'+paths.map((p,i)=>{let ex=collectionRows.find(x=>x.path===p),migrated=p!==original[i];return ex?`<div style="margin-top:7px">${esc(p)} ${migrated?'<span class="muted">(renamed root)</span> ':''}<span class="ok">(existing)</span> <button class="smallbtn" onclick="addRec('${ex.key}')">Select</button></div>`:`<div style="margin-top:7px">${esc(p)} ${migrated?'<span class="muted">(renamed root)</span> ':''}<span class="warn">(doesn't exist)</span> <button class="smallbtn" onclick="createRecByIndex(${i})">Create & select</button></div>`}).join('');
  window._recPaths=paths;
}
function createRecByIndex(i){let p=(window._recPaths||[])[i];if(p)createRec(p)}
function addRec(k){locationSet.add(k);renderLocation();filingMsg.textContent='Selected. Click Save locations.'}
async function createRec(p){try{filingMsg.textContent='Creating folder…';let r=await api('/collections/create-path',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path:p})});if(!r.key)throw Error('Folder was created but no collection key was returned');await refreshTrees();locationSet.add(r.key);treeData.forEach(n=>locOpen.add(n.key));renderLocation();filingMsg.textContent=(r.message||'Folder ready')+' · selected. Click Save locations.'}catch(e){filingMsg.textContent='Error: '+e.message}}
async function loadLocations(){let x=await api('/item/'+selectedKey+'/locations');locationSet=new Set(x.collection_keys||[]);removeInbox.checked=false;removeInboxWrap.style.display=x.in_inbox?'block':'none';treeData.forEach(n=>locOpen.add(n.key));renderLocation()}
async function applyFiling(){if(!selectedKey)return;try{filingMsg.textContent='Saving…';let r=await api('/filing',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({item_key:selectedKey,collection_keys:[...locationSet],remove_inbox:removeInbox.checked})});filingMsg.textContent=r.message;closeModal('locationModal');await refreshTrees();await refreshCounts();if(selectedKey)await selectItem(selectedKey)}catch(e){filingMsg.textContent=e.message}}
