let relatedRequestId=0;
async function findRelated(force=false){
  if(!selectedKey)return;
  const rid=++relatedRequestId, key=selectedKey;
  let b=document.getElementById('relatedBtn'),old=b.textContent;b.disabled=true;b.textContent=force?'Refreshing…':'Finding Related…';
  relatedPanel.style.display='block';related.innerHTML='<div class="muted">Screening the local Library…</div>';
  const controller=new AbortController(); const timer=setTimeout(()=>controller.abort(),35000);
  // Show useful phase feedback even though the endpoint remains a single request.
  const phaseTimer=setTimeout(()=>{if(rid===relatedRequestId)related.innerHTML='<div class="muted">Local candidates found or being checked · labeling scientific relationships…</div>'},700);
  try{
    let r=await fetch('/related/'+encodeURIComponent(key)+(force?'?refresh=1':''),{signal:controller.signal});
    let text=await r.text(),x;try{x=JSON.parse(text)}catch(_){throw Error('Expected JSON from Related Papers, got '+text.slice(0,180))}
    if(!r.ok)throw Error(x.message||x.error||r.status); if(rid!==relatedRequestId)return;
    let meta=`Entire Library · ${esc(x.screened_locally||0)} papers screened locally · ${esc(x.candidates||0)} candidates · ${esc(x.gemini_calls||0)} LLM call${Number(x.gemini_calls||0)===1?'':'s'}${x.cached?' · saved result':''}`;
    if(x.degraded)meta+=' · local fallback';
    let notice=x.degraded&&x.degradation_reason?`<div class="warn" style="margin:7px 0">${esc(x.degradation_reason)}</div>`:'';
    let rows=(x.related||[]).map(r=>`<div class="relatedRow" onclick="selectItem('${r.key}')"><div><b>${esc(r.title)}</b> ${esc(r.year||'')}</div><div class="muted">${esc(String(r.relationship||'').replaceAll('-',' '))} · ${esc(r.score)}/100 · ${esc(r.evidence||'metadata')}</div><div>${esc(r.reason||'')}</div></div>`).join('');
    related.innerHTML=`<div class="relatedMeta">${meta}</div>${notice}${rows||'<div class="muted">No sufficiently related papers found.</div>'}`;
    let rb=document.getElementById('refreshRelatedBtn');if(rb)rb.style.display='inline-block';relatedPanel.scrollIntoView({behavior:'smooth',block:'start'});
  }catch(e){if(rid!==relatedRequestId)return;related.innerHTML=e.name==='AbortError'?'<div class="warn">Related Papers timed out. The server will no longer wait indefinitely; try Refresh related once.</div>':'<div class="err">Error: '+esc(e.message)+'</div>'}
  finally{clearTimeout(timer);clearTimeout(phaseTimer);if(rid===relatedRequestId){b.disabled=false;b.textContent=old}}
}
function closeRelated(){relatedRequestId++;relatedPanel.style.display='none';related.innerHTML=''}
