function prettyConfig(x){let w=x.watch||{},l=x.limits||{};let rows=[];for(const k of ['research','methods','review']){let v=w[k]||{};rows.push(`<div class="k">${k[0].toUpperCase()+k.slice(1)}</div><div>${esc(v.frequency||'-')} · threshold ${esc(v.threshold||'-')} · ${esc((v.sources||[]).join(', '))}<br><span class="muted">Query: ${esc(v.query||'-')}</span></div>`)}rows.push(`<div class="k">LLM screening/day</div><div>${esc(l.max_llm_screenings_per_day||'-')}</div>`);rows.push(`<div class="k">Source requests/day</div><div>${esc(l.max_source_requests_per_day||'-')}</div>`);return rows.join('')}
