function flattenObj(o,p='',out={}){for(const [k,v] of Object.entries(o||{})){let q=p?p+'.'+k:k;if(v&&typeof v==='object'&&!Array.isArray(v))flattenObj(v,q,out);else out[q]=v}return out}
function diffConfig(oldCfg,newCfg){let a=flattenObj(oldCfg||{}),b=flattenObj(newCfg||{}),added=[],removed=[],modified=[];for(const k of Object.keys(b)){if(!(k in a))added.push([k,b[k]]);else if(JSON.stringify(a[k])!==JSON.stringify(b[k]))modified.push([k,a[k],b[k]])}for(const k of Object.keys(a))if(!(k in b))removed.push([k,a[k]]);return {added,removed,modified}}
function fmtVal(v){return Array.isArray(v)?v.join(', '):(v===null?'null':String(v))}
function renderDiff(d){let blocks=[];if(d.added.length)blocks.push('<b>Added</b><br>'+d.added.map(x=>'• '+esc(x[0])+': '+esc(fmtVal(x[1]))).join('<br>'));if(d.modified.length)blocks.push('<b>Modified</b><br>'+d.modified.map(x=>'• '+esc(x[0])+': '+esc(fmtVal(x[1]))+' → '+esc(fmtVal(x[2]))).join('<br>'));if(d.removed.length)blocks.push('<b>Removed</b><br>'+d.removed.map(x=>'• '+esc(x[0])+': '+esc(fmtVal(x[1]))).join('<br>'));return blocks.join('<br><br>')||'<b>No changes detected.</b>'}
async function compileWatch(){let t=watchText.value.trim();if(!t)return;let b=event?.target;try{watchMsg.textContent='Analyzing instructions…';if(b){b.disabled=true;b.textContent='Analyzing…'}let x=await api('/watch/compile',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({instructions:t})});proposedWatch=x.proposed;let base={watch:(lastWatchSettings||{}).watch||{},limits:(lastWatchSettings||{}).limits||{},inbox_retention_days:(lastWatchSettings||{}).inbox_retention_days,profile:(lastWatchSettings||{}).profile||{}};let d=diffConfig(base,proposedWatch);watchPreview.innerHTML=renderDiff(d);applyWatchBtn.style.display=(d.added.length||d.modified.length||d.removed.length)?'inline-block':'none';watchMsg.textContent='Changes ready · '+(x.provider==='local'?('Local LLM '+(x.model||'' )+' · 0 LLM calls'):(x.fallback?'Primary LLM fallback · 1 LLM call':'Primary LLM · 1 LLM call'))}catch(e){proposedWatch=null;applyWatchBtn.style.display='none';watchPreview.innerHTML='<span class="muted">No pending changes.</span>';watchMsg.textContent='Error: '+e.message}finally{if(b){b.disabled=false;b.textContent='Preview Changes'}}}
async function applyWatch(){if(!proposedWatch)return;try{applyWatchBtn.disabled=true;applyWatchBtn.textContent='Applying…';watchMsg.textContent='Applying settings…';await api('/watch/apply',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({proposed:proposedWatch})});let base={watch:(lastWatchSettings||{}).watch||{},limits:(lastWatchSettings||{}).limits||{},inbox_retention_days:(lastWatchSettings||{}).inbox_retention_days,profile:(lastWatchSettings||{}).profile||{}};let d=diffConfig(base,proposedWatch);watchPreview.innerHTML='<b>Applied ✓</b><br><br>'+renderDiff(d);watchMsg.textContent=`Settings saved ✓ — ${d.added.length} added, ${d.modified.length} modified, ${d.removed.length} removed`;applyWatchBtn.style.display='none';lastWatchSettings=await api('/watch/settings')}catch(e){watchMsg.textContent='Error: '+e.message}finally{applyWatchBtn.disabled=false;applyWatchBtn.textContent='Apply Proposed Changes'}}
async function clearSearchConditions(){if(!confirm('Clear current Watch search queries and free-text search instructions?'))return;try{watchMsg.textContent='Clearing search conditions…';let x=await api('/watch/clear-search',{method:'POST'});watchText.value='';proposedWatch=null;applyWatchBtn.style.display='none';watchPreview.innerHTML='<span class="muted">No active search query.</span>';watchMsg.textContent=x.message+' ✓';await loadWatch()}catch(e){watchMsg.textContent='Error: '+e.message}}
async function refreshCounts(){try{let l=await api('/cache');if(!l.ready){total.textContent=summarized.textContent=pending.textContent=nopdf.textContent='–';msg.textContent=l.syncing?'Library sync is running…':'No local library cache yet. Click Sync Library once.';return}total.textContent=l.total;summarized.textContent=l.summarized;pending.textContent=l.pending;nopdf.textContent=l.no_pdf}catch(e){msg.textContent='Local cache error: '+e.message}}
