async function runWatch(force=false){watchMsg.textContent=force?'Force-searching enabled sources…':'Running due searches…';try{let x=await api('/watch/run',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({force})});let ran=(x.ran_categories||[]).join(', ')||'none', skipped=(x.skipped_categories||[]).join(', ')||'none';watchMsg.textContent=(x.message||'Watch finished')+' · ran: '+ran+' · skipped: '+skipped;await loadCandidates()}catch(e){watchMsg.textContent=e.message}}
