function setWatchTab(t){watchTab=t;candidateSelected.clear();['Candidates','Maybe','History'].forEach(n=>{let b=document.getElementById('tab'+n);if(b)b.className=(t===n.toLowerCase()?'smallbtn':'secondary smallbtn')});renderWatchList()}
function candidateRow(c,mode){let buttons=mode==='candidates'?`<button class="smallbtn" onclick="acceptCandidate('${c.id}')">Accept</button><button class="secondary smallbtn" onclick="maybeCandidate('${c.id}')">Maybe</button><button class="secondary smallbtn" onclick="rejectCandidate('${c.id}')">Reject</button>`:mode==='maybe'?`<button class="smallbtn" onclick="acceptCandidate('${c.id}')">Accept</button><button class="secondary smallbtn" onclick="restoreCandidate('${c.id}')">Restore</button><button class="secondary smallbtn" onclick="rejectCandidate('${c.id}')">Reject</button>`:`<button class="secondary smallbtn" onclick="restoreCandidate('${c.id}')">Restore</button>`;return `<div style="border-top:1px solid #eee;padding:10px 0;display:grid;grid-template-columns:24px 1fr"><input class="candCheck" data-id="${c.id}" type="checkbox" onchange="toggleCandidate('${c.id}',this.checked)"><div><div class="candidateTitle">${mathEsc(c.title)}</div><div class="candidateMeta">${esc(c.year||'')} · ${esc(c.source)} · ${esc(c.category||'')} · ${mode==='history'?esc(c.status||''):('Score '+esc(c.score)+' / 100')}</div><div class="muted">${mathEsc(c.reason||'')}</div>${c.abstract&&mode!=='history'?`<details style="margin-top:5px"><summary class="muted">Abstract</summary><div style="font-size:13px;line-height:1.45;margin-top:5px">${mathEsc(c.abstract)}</div></details>`:''}<div class="actions" style="margin-top:6px">${buttons}${c.url?`<button class="secondary smallbtn" onclick="window.open('${esc(c.url)}','_blank')">Open</button>`:''}</div></div></div>`}
function renderWatchList(){let rows=watchData[watchTab]||[];let actions=watchTab==='candidates'?`<button class="smallbtn" onclick="batchCandidates('accept')">Accept</button><button class="secondary smallbtn" onclick="batchCandidates('maybe')">Maybe</button><button class="secondary smallbtn" onclick="batchCandidates('reject')">Reject</button>`:watchTab==='maybe'?`<button class="smallbtn" onclick="batchCandidates('accept')">Accept</button><button class="secondary smallbtn" onclick="batchRestore()">Restore</button><button class="secondary smallbtn" onclick="batchCandidates('reject')">Reject</button>`:`<button class="secondary smallbtn" onclick="batchRestore()">Restore</button>`;candidates.innerHTML=rows.length?`<div class="candidateToolbar"><label><input type="checkbox" onchange="selectAllCandidates(this.checked)"> Select all</label><span id="batchCount" class="muted">0 selected</span>${actions}</div><div class="candidateList">`+rows.map(c=>candidateRow(c,watchTab)).join('')+'</div>':`<span class="muted">No ${watchTab} papers.</span>`;updateBatchBar()}
async function batchRestore(){for(const id of [...candidateSelected]){try{await api('/watch/candidate/'+id+'/restore',{method:'POST'})}catch(e){}}candidateSelected.clear();await loadCandidates()}
