async function loadCandidates(){try{let x=await api('/watch/candidates');watchData={candidates:x.candidates||[],maybe:x.maybe||[],history:x.history||[]};let st=x.state||{},cats=st.categories||{};watchSchedule.innerHTML=['research','methods','review'].map(k=>{let c=cats[k]||{};return `<b>${k[0].toUpperCase()+k.slice(1)}</b>: ${c.last_checked?'checked '+esc(c.last_checked.replace('T',' ')):'not checked yet'} · ${c.new_candidates||0} new · next ${esc(c.next_check||'due now')}`}).join('<br>');tabCandidates.textContent='Candidates ('+watchData.candidates.length+')';tabMaybe.textContent='Maybe ('+watchData.maybe.length+')';tabHistory.textContent='History ('+watchData.history.length+')';candidateSelected.clear();renderWatchList()}catch(e){candidates.textContent=e.message}}
async function acceptCandidate(id,confirmed=false){
  watchMsg.textContent='Accepting paper · checking public PDF and length…';
  try{
    let r=await fetch('/watch/candidate/'+id+'/accept',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirm_long:confirmed})});
    let x=await r.json();
    if(r.status===409&&x.requires_confirmation){
      watchMsg.textContent='Long-paper confirmation required';
      if(confirm(x.message+'\n\nAccept and run the full Summary anyway?')) return acceptCandidate(id,true);
      watchMsg.textContent='Accept cancelled — no Zotero item or Summary created.'; return;
    }
    if(!r.ok)throw Error(x.message||x.error||r.status);
    watchMsg.textContent=x.message;await loadCandidates();await refreshCounts();await refreshTrees();
  }catch(e){watchMsg.textContent=e.message}
}
async function maybeCandidate(id){try{let x=await api('/watch/candidate/'+id+'/maybe',{method:'POST'});watchMsg.textContent=x.message;await loadCandidates()}catch(e){watchMsg.textContent=e.message}}
async function rejectCandidate(id){try{let x=await api('/watch/candidate/'+id+'/reject',{method:'POST'});watchMsg.textContent=x.message;await loadCandidates()}catch(e){watchMsg.textContent=e.message}}

function safeRun(fn){Promise.resolve().then(fn).catch(()=>{})}
function refreshAll(){safeRun(refreshStatus);safeRun(refreshSettings);safeRun(refreshCounts);safeRun(refreshTrees);safeRun(refreshUsage)}
// Every panel initializes independently. A failure in one panel can never block the rest of the dashboard.
refreshAll();safeRun(refreshNeedsFiling);safeRun(refreshComparisonHistoryCount);safeRun(loadWatch);safeRun(loadCandidates);setInterval(()=>safeRun(refreshStatus),3000);setInterval(()=>safeRun(refreshUsage),30000);

let knowledgeSessionId=null,knowledgeLastAnswer='',knowledgeLastSources=[];
function renderKnowledgeMarkdown(text){
  let s=mathEsc(text||'');s=s.replace(/^###\s+(.+)$/gm,'<h3>$1</h3>').replace(/^##\s+(.+)$/gm,'<h3>$1</h3>').replace(/^#\s+(.+)$/gm,'<h3>$1</h3>');s=s.replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>');s=s.replace(/^\s*[-*]\s+(.+)$/gm,'<div class="knowledgeBullet">• $1</div>');s=s.replace(/\n{2,}/g,'<br><br>').replace(/\n/g,'<br>');return s;
}
function renderKnowledgeSources(rows){knowledgeLastSources=rows||[];knowledgeSources.style.display=rows.length?'block':'none';knowledgeSources.className='knowledgeSources';knowledgeSources.innerHTML=rows.length?'<b>Library sources</b>'+rows.map(r=>`<div class="knowledgeSource">[${r.n}] <a onclick="selectItem('${r.key}');document.getElementById('workspace').scrollIntoView({behavior:'smooth'})">${esc(r.title)}</a> <span class="muted">${esc(r.year||'')} · ${r.evidence==='abstract'?'Abstract':'Metadata only'} · Local relevance: ${esc(r.relevance||'')}${r.has_pdf?' · PDF available':''}</span></div>`).join(''):''}
async function askKnowledge(){let q=knowledgeQuestion.value.trim();if(!q)return;resetComparisonView(true);comparisonRequestSeq++;let mode=knowledgeMode.value,b=knowledgeAskBtn,old=b.textContent;b.disabled=true;b.textContent=mode==='find'?'Finding…':'Thinking…';knowledgeAnswer.style.display='block';knowledgeAnswer.textContent='Working…';knowledgeSources.style.display='none';try{let scope=knowledgeScope,subs=knowledgeSubfolders;if(mode==='find'){knowledgeMsg.textContent='Local title/keyword → abstract rerank · 0 LLM calls';let x=await api('/knowledge/find',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:q,top_k:12,collection_key:scope.value,include_subcollections:subs.checked})});knowledgeLastAnswer=`Find Papers: ${q}`;knowledgeAnswer.innerHTML=`<b>${x.retrieved||0} relevant paper(s)</b> · 0 LLM calls`;renderKnowledgeSources(x.sources||[]);knowledgeMsg.textContent=`${x.screened||0} locally screened · ${x.prefiltered||0} abstract candidates · ${x.retrieved||0} returned · 0 LLM calls`;}else{knowledgeMsg.textContent='Local screening → abstract rerank → LLM synthesis';let x=await api('/knowledge/ask',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:q,top_k:6,collection_key:scope.value,include_subcollections:subs.checked,session_id:knowledgeSessionId,item_keys:[...librarySelected]})});knowledgeSessionId=x.session_id||knowledgeSessionId;knowledgeLastAnswer=x.answer||'';knowledgeAnswer.innerHTML=renderKnowledgeMarkdown(knowledgeLastAnswer);renderKnowledgeSources(x.sources||[]);knowledgeMsg.textContent=`${x.screened||0} locally screened · ${x.prefiltered||0} abstract candidates · ${x.retrieved||0} sent to LLM · ${x.gemini_calls||0} LLM call`;await loadKnowledgeSessions();}knowledgeQuestion.value='';}catch(e){knowledgeAnswer.textContent='Error: '+e.message;knowledgeMsg.textContent='Knowledge Agent failed'}finally{b.disabled=false;b.textContent=old}}
async function enrichKnowledgeMetadata(){knowledgeMsg.textContent='Checking metadata APIs… 0 LLM calls';try{let x=await api('/knowledge/enrich-metadata',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({collection_key:knowledgeScope.value,include_subcollections:knowledgeSubfolders.checked})});knowledgeMsg.textContent=x.message;if(x.updated){await waitForCache();await refreshCounts();await refreshTrees()}}catch(e){knowledgeMsg.textContent='Metadata enrichment failed: '+e.message}}
function clearKnowledge(){knowledgeQuestion.value='';knowledgeAnswer.textContent='';knowledgeAnswer.style.display='none';knowledgeSources.innerHTML='';knowledgeSources.style.display='none';knowledgeMsg.textContent=''}
async function newKnowledgeSession(){resetComparisonView(true);comparisonRequestSeq++;knowledgeSessionId=null;clearKnowledge();knowledgeMsg.textContent='New conversation';}
async function loadKnowledgeSessions(){try{let x=await api('/knowledge/sessions');knowledgeHistory.innerHTML=(x.sessions||[]).map(s=>`<div class="knowledgeHistoryRow"><a onclick="openKnowledgeSession('${s.id}')">${esc(s.title)}</a><span class="muted">${s.turns} turn(s) · ${esc((s.updated_at||'').replace('T',' '))}</span><button class="secondary smallbtn" onclick="deleteKnowledgeSession('${s.id}')">Delete</button></div>`).join('')||'<span class="muted">No saved conversations.</span>'}catch(e){knowledgeHistory.textContent=e.message}}
async function toggleKnowledgeHistory(){knowledgeHistory.style.display=knowledgeHistory.style.display==='none'?'block':'none';if(knowledgeHistory.style.display==='block')await loadKnowledgeSessions()}
async function openKnowledgeSession(id){let x=await api('/knowledge/session/'+id);knowledgeSessionId=id;let turns=(x.session.turns||[]);knowledgeConversation.innerHTML=turns.map(t=>`<div class="knowledgeTurn"><div class="muted">${esc((t.ts||'').replace('T',' '))}</div><b>Q:</b> ${esc(t.question)}<div class="knowledgeTurnAnswer">${renderKnowledgeMarkdown(t.answer||'')}</div></div>`).join('');knowledgeHistory.style.display='none';knowledgeMsg.textContent=`Loaded ${turns.length} turn(s). Follow-up context stays compact.`}
async function deleteKnowledgeSession(id){if(!confirm('Delete this Knowledge conversation?'))return;await api('/knowledge/session/'+id,{method:'DELETE'});if(knowledgeSessionId===id){knowledgeSessionId=null;knowledgeConversation.innerHTML=''}await loadKnowledgeSessions()}
function exportKnowledgeMarkdown(){if(!knowledgeLastAnswer&&!knowledgeLastSources.length)return;let md='# Knowledge Agent\n\n'+knowledgeLastAnswer+'\n\n## Library sources\n'+knowledgeLastSources.map(r=>`- [${r.n}] ${r.title} (${r.year||''}) — ${r.evidence==='abstract'?'Abstract':'Metadata only'}, local relevance ${r.relevance||''}`).join('\n');let blob=new Blob([md],{type:'text/markdown;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='knowledge-answer.md';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
