function closeComparison(){resetComparisonView(true)}
async function refreshComparisonHistoryCount(){try{let x=await api('/library/comparisons');comparisonHistoryCache=x.comparisons||[];let e=document.getElementById('comparisonHistoryCount');if(e)e.textContent='('+comparisonHistoryCache.length+')'}catch(e){}}
function scheduleComparisonMatch(){clearTimeout(comparisonMatchTimer);let keys=[...librarySelected],seq=++comparisonMatchSeq,btn=document.getElementById('compareSelectedBtn');if(btn){btn.textContent='Compare selected';btn.dataset.matchId=''}if(keys.length<2||keys.length>5)return;comparisonMatchTimer=setTimeout(async()=>{try{let x=await api('/library/comparison-match',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({item_keys:keys})});if(seq!==comparisonMatchSeq)return;let b=document.getElementById('compareSelectedBtn');if(!b)return;if(x.matched){b.textContent='Open comparison';b.dataset.matchId=x.id||''}else{b.textContent='Compare selected';b.dataset.matchId=''}}catch(e){}},180)}
async function showPaperDetails(){if(!selectedKey)return;let x=await api('/item/'+selectedKey+'/details'),r=x.item||{},d=document.getElementById('paperDetails');d.style.display='block';d.innerHTML=`<b>Published:</b> ${esc(dateOnly(r.published||r.year||'Unknown'))}<br><b>DOI:</b> ${esc(r.doi||'Unavailable')}<br><b>PDF:</b> ${r.has_pdf?'Available':'Missing'} · <b>Research Card:</b> ${x.has_card?'Available':'Missing'}<br><b>Collections:</b> ${esc((x.locations||[]).join(' · ')||'Unfiled')}<div class="abstract"><b>Abstract</b><br>${esc(r.abstract||'No abstract available.')}</div>`}
let currentComparisonId=null,currentComparisonKeys=[],currentComparisonResult=null,currentComparisonSources=[],comparisonRequestSeq=0;
function renderComparison(result,sources){
  currentComparisonResult=result||{};currentComparisonSources=sources||[];
  comparisonLabel.textContent=result.label||'Paper comparison';
  let html='';if(result.overview)html+=`<div class="cmpOverview">${renderRichText(result.overview)}</div>`;
  let ds=result.dimensions||[];if(ds.length){html+='<div class="cmpSection"><h3>Comparison</h3><div class="cmpTableWrap"><table class="cmpTable"><thead><tr><th>Dimension</th>'+currentComparisonSources.map(s=>`<th>${esc(s.title)}</th>`).join('')+'</tr></thead><tbody>'+ds.map(d=>`<tr><th>${esc(d.name)}</th>`+(d.values||[]).map(v=>`<td>${renderRichText(v)}</td>`).join('')+'</tr>').join('')+'</tbody></table></div></div>'}
  const sec=(name,vals)=>{if(!(vals||[]).length)return '';return `<div class="cmpSection"><h3>${name}</h3>`+vals.map((v,i)=>`<div class="cmpPaper"><b>[${i+1}] ${esc((currentComparisonSources[i]||{}).title||'Paper')}</b><div>${renderRichText(v)}</div></div>`).join('')+'</div>'};
  html+=sec('Methods',result.methods)+sec('Reported Results',result.results)+sec('Limitations',result.limitations);if(result.takeaway)html+=`<div class="cmpSection"><h3>Takeaway</h3><div>${renderRichText(result.takeaway)}</div></div>`;
  comparisonBody.innerHTML=html;comparisonSources.innerHTML='<b>Sources</b>'+currentComparisonSources.map(s=>`<div class="knowledgeSource">[${s.n}] <a onclick="selectItem('${s.key}');document.getElementById('workspace').scrollIntoView({behavior:'smooth'})">${esc(s.title)}</a> <span class="muted">${esc(s.year||'')} · ${s.evidence==='abstract'?'Abstract':'Metadata only'}</span></div>`).join('');
}
function renderRichText(v){let s=mathEsc(String(v||''));s=s.replace(/&lt;br\s*\/?&gt;/gi,' ');s=s.replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>');s=s.replace(/^\s*---+\s*$/gm,'');s=s.replace(/\n{3,}/g,'\n\n').replace(/\n/g,'<br>');return s}
async function compareSelectedPapers(force=false){let keys=[...librarySelected];if(keys.length<2||keys.length>5){alert('Select 2 to 5 papers.');return}let btn=document.getElementById('compareSelectedBtn');if(!force&&btn&&btn.dataset.matchId){await openSavedComparison(btn.dataset.matchId);return}let req=++comparisonRequestSeq;resetComparisonView(false);comparisonRequestSeq=req;currentComparisonKeys=keys.slice();comparisonPanel.style.display='block';comparisonLabel.textContent='Comparing…';comparisonMeta.textContent=`${keys.length} papers · Checking history…`;comparisonBody.innerHTML='<div class="muted">Checking saved comparisons…</div>';comparisonSources.innerHTML='';comparisonPanel.scrollIntoView({behavior:'smooth',block:'start'});try{let x=await api('/library/compare',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({item_keys:keys,force})});if(req!==comparisonRequestSeq)return;currentComparisonId=x.id;currentComparisonKeys=(x.sources||[]).map(s=>s.key);renderComparison(x.result||{},x.sources||[]);comparisonMeta.textContent=`${currentComparisonKeys.length} papers · Abstract-based · ${x.cached?'saved result · 0 LLM calls':('new result · '+(x.gemini_calls||1)+' LLM call')} · v${x.version||1}`;await refreshComparisonHistoryCount();scheduleComparisonMatch()}catch(e){if(req!==comparisonRequestSeq)return;comparisonLabel.textContent='Comparison failed';comparisonMeta.textContent='';comparisonBody.textContent='Error: '+e.message;comparisonSources.innerHTML=''}}
async function regenerateComparison(){if(!currentComparisonKeys.length)return;librarySelected=new Set(currentComparisonKeys);renderLibrary();updateLibraryBatch();await compareSelectedPapers(true)}
async function loadComparisonHistory(){let x=await api('/library/comparisons');comparisonHistoryCache=x.comparisons||[];let e=document.getElementById('comparisonHistoryCount');if(e)e.textContent='('+comparisonHistoryCache.length+')';comparisonHistory.innerHTML=comparisonHistoryCache.length?comparisonHistoryCache.map(c=>`<div class="knowledgeHistoryRow" onclick="openSavedComparison('${c.id}')"><b>${esc(c.label)}</b><br><span class="muted">${c.paper_count} papers · ${c.version_count} version${c.version_count===1?'':'s'}</span></div>`).join(''):'<span class="muted">No saved comparisons yet.</span>';return comparisonHistoryCache}
async function toggleComparisonHistory(){comparisonPanel.style.display='block';comparisonHistory.style.display=comparisonHistory.style.display==='none'?'block':'none';if(comparisonHistory.style.display==='block')await loadComparisonHistory()}
async function openComparisonHistoryFromLibrary(){resetComparisonView(false);comparisonPanel.style.display='block';comparisonLabel.textContent='Saved Comparisons';comparisonMeta.textContent='Open a previous paper comparison';comparisonHistory.style.display='block';comparisonBody.innerHTML='';comparisonSources.innerHTML='';await loadComparisonHistory();comparisonPanel.scrollIntoView({behavior:'smooth',block:'start'})}
async function openSavedComparison(id){let req=++comparisonRequestSeq;resetComparisonView(false);comparisonRequestSeq=req;comparisonPanel.style.display='block';comparisonLabel.textContent='Loading comparison…';comparisonMeta.textContent='Saved result · 0 LLM calls';comparisonBody.innerHTML='<div class="muted">Loading saved comparison…</div>';comparisonSources.innerHTML='';try{let x=await api('/library/comparison/'+id);if(req!==comparisonRequestSeq)return;currentComparisonId=id;currentComparisonKeys=(x.sources||[]).map(s=>s.key);renderComparison(x.result||{},x.sources||[]);comparisonMeta.textContent=`${currentComparisonKeys.length} papers · Abstract-based · saved result · 0 LLM calls · v${x.version||1}`;comparisonHistory.style.display='none'}catch(e){if(req!==comparisonRequestSeq)return;comparisonLabel.textContent='Comparison failed';comparisonBody.textContent='Error: '+e.message}}
function exportComparisonMarkdown(){if(!currentComparisonResult)return;let r=currentComparisonResult,s=currentComparisonSources||[],lines=['# '+(r.label||'Paper comparison'),''];if(r.overview)lines.push(r.overview,'');for(const d of (r.dimensions||[])){lines.push('## '+d.name);(d.values||[]).forEach((v,i)=>lines.push(`- [${i+1}] ${v}`));lines.push('')}[['Methods',r.methods],['Reported Results',r.results],['Limitations',r.limitations]].forEach(([n,a])=>{if((a||[]).length){lines.push('## '+n);a.forEach((v,i)=>lines.push(`- [${i+1}] ${v}`));lines.push('')}});if(r.takeaway)lines.push('## Takeaway',r.takeaway,'');lines.push('## Sources');s.forEach(x=>lines.push(`[${x.n}] ${x.title} (${x.year||''})`));let blob=new Blob([lines.join('\n')],{type:'text/markdown'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=(r.label||'comparison').replace(/[^a-z0-9_-]+/gi,'_')+'.md';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function askSelectedPapers(){if(!librarySelected.size)return;resetComparisonView(true);comparisonRequestSeq++;knowledgeQuestion.focus();knowledgeQuestion.placeholder='Ask only the '+librarySelected.size+' selected papers…';knowledgeMsg.textContent=librarySelected.size+' selected papers locked as scope'}
async function showNeedsFiling(){let x=await api('/library/needs-filing');if(!x.items.length){alert('No papers need filing.');return}librarySelected=new Set(x.items.map(r=>r.key));treeData.forEach(n=>libOpen.add(n.key));renderLibrary();updateLibraryBatch();document.getElementById('libraryTree').scrollIntoView({behavior:'smooth'})}
async function refreshNeedsFiling(){try{let x=await api('/library/needs-filing'),e=document.getElementById('needsFilingCount');if(e)e.textContent='('+x.count+')'}catch(e){}}
